/**
 * ReadServiceClient — typed HTTP client for the Umbra Indexer Read Service.
 *
 * All responses are protobuf-encoded binary.
 *
 * @example
 * ```typescript
 * const client = new ReadServiceClient({ endpoint: "http://localhost:8082" });
 * const stats = await client.getStats();
 * const proof = await client.getProof(0, 42);
 * const utxos = await client.getUtxoData({ start: 0, limit: 100 });
 * ```
 */

import {
  fromBinary,
  type BasicHealthResponse as ProtoBasicHealth,
  BasicHealthResponseSchema,
  type DetailedHealthResponse as ProtoDetailedHealth,
  DetailedHealthResponseSchema,
  type LivenessResponse as ProtoLiveness,
  LivenessResponseSchema,
  type ReadinessResponse as ProtoReadiness,
  ReadinessResponseSchema,
  type ProofResponse as ProtoProof,
  ProofResponseSchema,
  type BatchProofResponse as ProtoBatchProof,
  BatchProofResponseSchema,
  type UtxoResponse as ProtoUtxo,
  UtxoResponseSchema,
  type UtxoColumnarResponse as ProtoUtxoColumnar,
  UtxoColumnarResponseSchema,
  type StatsResponse as ProtoStats,
  StatsResponseSchema,
  type TreeInfoResponse as ProtoTreeInfo,
  TreeInfoResponseSchema,
  type SingleUtxoResponse as ProtoSingleUtxo,
  SingleUtxoResponseSchema,
} from "@umbra-privacy/indexer-proto-gen";
import type { GenMessage } from "@bufbuild/protobuf/codegenv2";
import type { Message } from "@bufbuild/protobuf";

import { IndexerReadError } from "./errors.js";
import type {
  BasicHealthResponse,
  BatchProofResponse,
  DetailedHealthResponse,
  LivenessResponse,
  ProofResponse,
  ReadServiceClientConfig,
  ReadinessResponse,
  StatsResponse,
  TreeInfoResponse,
  UtxoColumnarResponse,
  UtxoDataResponse,
  UtxoRequest,
  UtxoResponse,
} from "./types.js";

const ACCEPT_PROTOBUF = "application/protobuf";

export class ReadServiceClient {
  private readonly endpoint: string;
  private readonly fetchFn: typeof globalThis.fetch;

  constructor(config: ReadServiceClientConfig) {
    this.endpoint = config.endpoint.replace(/\/+$/, "");
    this.fetchFn = config.fetch ?? globalThis.fetch.bind(globalThis);
  }

  // ===========================================================================
  // Health
  // ===========================================================================

  async health(): Promise<BasicHealthResponse> {
    return this.get<BasicHealthResponse, ProtoBasicHealth>(
      "/health",
      "health",
      BasicHealthResponseSchema,
      protoToBasicHealth,
    );
  }

  async healthDetailed(): Promise<DetailedHealthResponse> {
    return this.get<DetailedHealthResponse, ProtoDetailedHealth>(
      "/health/detailed",
      "healthDetailed",
      DetailedHealthResponseSchema,
      protoToDetailedHealth,
    );
  }

  async liveness(): Promise<LivenessResponse> {
    return this.get<LivenessResponse, ProtoLiveness>(
      "/health/liveness",
      "liveness",
      LivenessResponseSchema,
      protoToLiveness,
    );
  }

  async readiness(): Promise<ReadinessResponse> {
    return this.get<ReadinessResponse, ProtoReadiness>(
      "/health/readiness",
      "readiness",
      ReadinessResponseSchema,
      protoToReadiness,
    );
  }

  // ===========================================================================
  // Stats
  // ===========================================================================

  /** Get global UTXO statistics. */
  async getStats(): Promise<StatsResponse> {
    return this.get<StatsResponse, ProtoStats>(
      "/v1/stats",
      "getStats",
      StatsResponseSchema,
      protoToStatsResponse,
    );
  }

  // ===========================================================================
  // Tree Info
  // ===========================================================================

  /**
   * Get metadata for a specific Merkle tree.
   *
   * @param treeIndex - The Merkle tree index.
   */
  async getTreeInfo(treeIndex: bigint): Promise<TreeInfoResponse> {
    return this.get<TreeInfoResponse, ProtoTreeInfo>(
      `/v1/trees/${treeIndex}`,
      "getTreeInfo",
      TreeInfoResponseSchema,
      protoToTreeInfoResponse,
    );
  }

  // ===========================================================================
  // Merkle Proof
  // ===========================================================================

  /**
   * Get a Merkle proof for a specific leaf in a tree.
   *
   * @param treeIndex - The Merkle tree index.
   * @param insertionIndex - The leaf index within the tree.
   */
  async getProof(treeIndex: bigint, insertionIndex: bigint): Promise<ProofResponse> {
    return this.get<ProofResponse, ProtoProof>(
      `/v1/trees/${treeIndex}/proof/${insertionIndex}`,
      "getProof",
      ProofResponseSchema,
      protoToProofResponse,
    );
  }

  /**
   * Get Merkle proofs for multiple leaves in a single atomic request.
   *
   * All proofs are generated under a single tree read lock, guaranteeing
   * they share the same Merkle root.
   *
   * @param treeIndex - The Merkle tree index.
   * @param insertionIndices - Leaf indices within the tree (max 8).
   */
  async getBatchProof(
    treeIndex: bigint,
    insertionIndices: bigint[],
  ): Promise<BatchProofResponse> {
    return this.post<BatchProofResponse, ProtoBatchProof>(
      `/v1/trees/${treeIndex}/proofs`,
      "getBatchProof",
      BatchProofResponseSchema,
      protoBatchProofToResponse,
      { insertion_indices: insertionIndices.map(Number) },
    );
  }

  // ===========================================================================
  // UTXO Data
  // ===========================================================================

  /**
   * Fetch UTXO data by absolute index range with pagination.
   *
   * @param params - Query parameters (start, end, limit — all optional).
   */
  async getUtxoData(params: UtxoRequest = {}): Promise<UtxoResponse> {
    const query = buildQuery(params);
    return this.get<UtxoResponse, ProtoUtxo>(
      `/v1/utxos${query}`,
      "getUtxoData",
      UtxoResponseSchema,
      protoToUtxoResponse,
    );
  }

  /**
   * Fetch UTXO data in columnar layout for maximum compression.
   *
   * Sends `X-Response-Layout: columnar` header. Data is transposed into
   * column arrays instead of row arrays for better compression ratios.
   *
   * @param params - Query parameters (start, end, limit — all optional).
   */
  async getUtxoDataColumnar(params: UtxoRequest = {}): Promise<UtxoColumnarResponse> {
    const query = buildQuery(params);
    return this.get<UtxoColumnarResponse, ProtoUtxoColumnar>(
      `/v1/utxos${query}`,
      "getUtxoDataColumnar",
      UtxoColumnarResponseSchema,
      protoToUtxoColumnarResponse,
      { "X-Response-Layout": "columnar" },
    );
  }

  /**
   * Fetch a single UTXO by its absolute index.
   *
   * Returns `null` if the UTXO does not exist (404).
   *
   * @param absoluteIndex - The global absolute index across all trees.
   */
  async getUtxo(absoluteIndex: bigint): Promise<UtxoDataResponse | null> {
    try {
      const proto = await this.get<ProtoSingleUtxo, ProtoSingleUtxo>(
        `/v1/utxos/${absoluteIndex}`,
        "getUtxo",
        SingleUtxoResponseSchema,
        (p) => p,
      );
      return proto.utxo ? protoUtxoItemToJson(proto.utxo) : null;
    } catch (err) {
      if (err instanceof IndexerReadError && err.statusCode === 404) {
        return null;
      }
      throw err;
    }
  }

  /**
   * Fetch UTXOs scoped to a specific Merkle tree with pagination.
   *
   * @param treeIndex - The Merkle tree index.
   * @param params - Pagination params (cursor = absolute_index, limit optional).
   */
  async getTreeUtxos(
    treeIndex: bigint,
    params: { cursor?: bigint; limit?: bigint } = {},
  ): Promise<UtxoResponse> {
    const parts: string[] = [];
    if (params.cursor !== undefined) parts.push(`cursor=${params.cursor}`);
    if (params.limit !== undefined) parts.push(`limit=${params.limit}`);
    const query = parts.length > 0 ? `?${parts.join("&")}` : "";
    return this.get<UtxoResponse, ProtoUtxo>(
      `/v1/trees/${treeIndex}/utxos${query}`,
      "getTreeUtxos",
      UtxoResponseSchema,
      protoToUtxoResponse,
    );
  }

  /**
   * Fetch all UTXO data with automatic pagination.
   *
   * Iterates through all pages starting from `start` up to an optional `end`.
   *
   * @param start - Starting absolute index (default: 0).
   * @param end - Optional ending absolute index (inclusive). Omit to fetch everything.
   * @param pageSize - Records per page (default: 1000, max: 5000).
   */
  async getAllUtxoData(
    start: bigint = 0n,
    end?: bigint,
    pageSize: bigint = 1000n,
  ): Promise<UtxoDataResponse[]> {
    const allItems: UtxoDataResponse[] = [];
    let cursor = start;

    while (true) {
      const response = await this.getUtxoData({ start: cursor, end, limit: pageSize });

      allItems.push(...response.items);

      if (!response.has_more || response.next_cursor === null) {
        break;
      }

      cursor = response.next_cursor;
    }

    return allItems;
  }

  // ===========================================================================
  // Internal helpers
  // ===========================================================================

  protected async get<T, P extends Message>(
    path: string,
    operation: string,
    protoSchema: GenMessage<P>,
    protoToJson: (proto: P) => T,
    extraHeaders?: Record<string, string>,
  ): Promise<T> {
    const url = `${this.endpoint}${path}`;

    let response: Response;
    try {
      response = await this.fetchFn(url, {
        method: "GET",
        headers: { Accept: ACCEPT_PROTOBUF, ...extraHeaders },
      });
    } catch (err) {
      throw new IndexerReadError(operation, `Network error: ${err}`, undefined, err as Error);
    }

    return this.handleResponse<T, P>(response, operation, protoSchema, protoToJson);
  }

  protected async post<T, P extends Message>(
    path: string,
    operation: string,
    protoSchema: GenMessage<P>,
    protoToJson: (proto: P) => T,
    body: unknown,
  ): Promise<T> {
    const url = `${this.endpoint}${path}`;

    let response: Response;
    try {
      response = await this.fetchFn(url, {
        method: "POST",
        headers: {
          Accept: ACCEPT_PROTOBUF,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      throw new IndexerReadError(operation, `Network error: ${err}`, undefined, err as Error);
    }

    return this.handleResponse<T, P>(response, operation, protoSchema, protoToJson);
  }

  protected async handleResponse<T, P extends Message>(
    response: Response,
    operation: string,
    protoSchema: GenMessage<P>,
    protoToJson: (proto: P) => T,
  ): Promise<T> {
    if (!response.ok) {
      let errorMessage: string;
      try {
        const errorBody = await response.text();
        errorMessage = errorBody || response.statusText;
      } catch {
        errorMessage = response.statusText;
      }
      throw new IndexerReadError(operation, errorMessage, response.status);
    }

    const contentType = response.headers.get("content-type") ?? "";

    if (contentType.includes("protobuf")) {
      try {
        const buffer = await response.arrayBuffer();
        const proto = fromBinary(protoSchema, new Uint8Array(buffer));
        return protoToJson(proto);
      } catch (err) {
        throw new IndexerReadError(
          operation,
          `Failed to decode protobuf response: ${err}`,
          response.status,
          err as Error,
        );
      }
    }

    // Fallback to JSON (e.g. error responses)
    try {
      return (await response.json()) as T;
    } catch (err) {
      throw new IndexerReadError(
        operation,
        `Failed to parse response: ${err}`,
        response.status,
        err as Error,
      );
    }
  }
}

// =============================================================================
// Query string builder
// =============================================================================

function buildQuery(params: UtxoRequest): string {
  const parts: string[] = [];
  if (params.start !== undefined) parts.push(`start=${params.start}`);
  if (params.end !== undefined) parts.push(`end=${params.end}`);
  if (params.limit !== undefined) parts.push(`limit=${params.limit}`);
  return parts.length > 0 ? `?${parts.join("&")}` : "";
}

// =============================================================================
// Proto-to-JSON conversion helpers
// =============================================================================

function bytesToBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(bytes).toString("base64");
  }
  let binary = "";
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function protoToBasicHealth(p: ProtoBasicHealth): BasicHealthResponse {
  return { status: p.status };
}

function protoToDetailedHealth(p: ProtoDetailedHealth): DetailedHealthResponse {
  return {
    status: p.status,
    version: p.version,
    timestamp: p.timestamp,
    uptime_seconds: p.uptimeSeconds,
    storage: p.storage
      ? { status: p.storage.status, connected: p.storage.connected }
      : { status: "unknown", connected: false },
  };
}

function protoToLiveness(p: ProtoLiveness): LivenessResponse {
  return { alive: p.alive };
}

function protoToReadiness(p: ProtoReadiness): ReadinessResponse {
  return { ready: p.ready, storage: p.storage };
}

function protoToStatsResponse(p: ProtoStats): StatsResponse {
  return {
    total_utxos: p.totalUtxos,
    latest_absolute_index: p.latestAbsoluteIndex !== undefined ? p.latestAbsoluteIndex : null,
  };
}

function protoToTreeInfoResponse(p: ProtoTreeInfo): TreeInfoResponse {
  return {
    tree_index: p.treeIndex,
    num_leaves: p.numLeaves,
    root: bytesToBase64(p.root),
    utxo_count: p.utxoCount,
  };
}

function protoToProofResponse(p: ProtoProof): ProofResponse {
  return {
    root: bytesToBase64(p.root),
    tree_index: p.treeIndex,
    insertion_index: p.insertionIndex,
    proof: p.proof.map(bytesToBase64),
    leaf: bytesToBase64(p.leaf),
  };
}

function protoBatchProofToResponse(p: ProtoBatchProof): BatchProofResponse {
  return {
    root: bytesToBase64(p.root),
    tree_index: p.treeIndex,
    proofs: p.proofs.map((entry) => ({
      insertion_index: entry.insertionIndex,
      proof: entry.proof.map(bytesToBase64),
      leaf: bytesToBase64(entry.leaf),
    })),
  };
}

function protoUtxoItemToJson(item: ProtoUtxo["items"][number]): UtxoDataResponse {
  return {
    absolute_index: item.absoluteIndex,
    tree_index: item.treeIndex,
    insertion_index: item.insertionIndex,
    final_commitment: bytesToBase64(item.finalCommitment),
    h1_version: readU128LE(item.h1Version),
    h1_commitment_index: readU128LE(item.h1CommitmentIndex),
    h1_sender_address: bytesToBase64(item.h1SenderAddress),
    h1_mint_address: bytesToBase64(item.h1MintAddress),
    h1_relayer_fixed_sol_fees: item.h1RelayerFixedSolFees,
    h1_year: BigInt(item.h1Year),
    h1_month: BigInt(item.h1Month),
    h1_day: BigInt(item.h1Day),
    h1_hour: BigInt(item.h1Hour),
    h1_minute: BigInt(item.h1Minute),
    h1_second: BigInt(item.h1Second),
    h1_pool_volume_spl: item.h1PoolVolumeSpl,
    h1_pool_volume_sol: item.h1PoolVolumeSol,
    h1_hash: bytesToBase64(item.h1Hash),
    h2_hash: bytesToBase64(item.h2Hash),
    aes_encrypted_data: bytesToBase64(item.aesEncryptedData),
    depositor_x25519_public_key: bytesToBase64(item.depositorX25519PublicKey),
    timestamp: item.timestamp,
    slot: item.slot,
    event_type: item.eventType,
  };
}

/** Read a u128 from 16 little-endian bytes and return as decimal string. */
function readU128LE(bytes: Uint8Array): string {
  if (bytes.length < 16) return "0";
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const lo = view.getBigUint64(0, true);
  const hi = view.getBigUint64(8, true);
  const value = (hi << 64n) | lo;
  return value.toString();
}

function protoToUtxoResponse(p: ProtoUtxo): UtxoResponse {
  return {
    items: p.items.map(protoUtxoItemToJson),
    has_more: p.hasMore,
    next_cursor: p.nextCursor !== undefined ? p.nextCursor : null,
    total_count: p.totalCount,
    start_index: p.startIndex,
    end_index: p.endIndex !== undefined ? p.endIndex : null,
  };
}

function protoToUtxoColumnarResponse(p: ProtoUtxoColumnar): UtxoColumnarResponse {
  const cols = p.columns;
  return {
    columns: cols
      ? {
          absolute_index: cols.absoluteIndex.slice(),
          tree_index: cols.treeIndex.slice(),
          insertion_index: cols.insertionIndex.slice(),
          final_commitment: cols.finalCommitment.map(bytesToBase64),
          h1_version: cols.h1Version.map(bytesToBase64),
          h1_commitment_index: cols.h1CommitmentIndex.map(bytesToBase64),
          h1_sender_address: cols.h1SenderAddress.map(bytesToBase64),
          h1_mint_address: cols.h1MintAddress.map(bytesToBase64),
          h1_relayer_fixed_sol_fees: cols.h1RelayerFixedSolFees.slice(),
          h1_year: cols.h1Year.map(BigInt),
          h1_month: cols.h1Month.map(BigInt),
          h1_day: cols.h1Day.map(BigInt),
          h1_hour: cols.h1Hour.map(BigInt),
          h1_minute: cols.h1Minute.map(BigInt),
          h1_second: cols.h1Second.map(BigInt),
          h1_pool_volume_spl: cols.h1PoolVolumeSpl.slice(),
          h1_pool_volume_sol: cols.h1PoolVolumeSol.slice(),
          h1_hash: cols.h1Hash.map(bytesToBase64),
          h2_hash: cols.h2Hash.map(bytesToBase64),
          aes_encrypted_data: cols.aesEncryptedData.map(bytesToBase64),
          depositor_x25519_public_key: cols.depositorX25519PublicKey.map(bytesToBase64),
          timestamp: cols.timestamp.slice(),
          slot: cols.slot.slice(),
          event_type: cols.eventType.slice(),
        }
      : null,
    count: BigInt(p.count),
    has_more: p.hasMore,
    next_cursor: p.nextCursor !== undefined ? p.nextCursor : null,
    total_count: p.totalCount,
    start_index: p.startIndex,
    end_index: p.endIndex !== undefined ? p.endIndex : null,
  };
}
