/**
 * Error class for Indexer Read Service client operations.
 */
export class IndexerReadError extends Error {
  public readonly operation: string;
  public readonly statusCode: number | undefined;

  constructor(operation: string, message: string, statusCode?: number, cause?: Error) {
    super(`Read service '${operation}' failed: ${message}`);
    this.name = "IndexerReadError";
    this.operation = operation;
    this.statusCode = statusCode;
    this.cause = cause;
  }
}
